            className: 'dvb-input dvb-input-mono',
            type: 'number',
            step: 'any',
            placeholder: '—',
            value: draft ? draft.alarmMin : point.alarmMin == null ? '' : point.alarmMin,
            onChange: (e) => patchDraft(point.id, { alarmMin: e.target.value }),
